// Mock Data generated by ChatGPT
const organisations = [
    { organisationId: 1, name: "ABC Company", location: "Ang Mo Kio" },
    { organisationId: 2, name: "XYZ School", location: "Jurong West" }
];

const wasteRecords = [
    // First Week: 1–7 November
    { wasteId: 1, organisationId: 1, wasteType: "Plastic", quantity: 10, disposalMethod: "Recycling", dateRecorded: "2026-11-01" },
    { wasteId: 2, organisationId: 1, wasteType: "Paper", quantity: 15, disposalMethod: "Recycling", dateRecorded: "2026-11-03" },
    { wasteId: 3, organisationId: 2, wasteType: "Plastic", quantity: 8, disposalMethod: "Recycling", dateRecorded: "2026-11-05" },

    // Second Week: 8–14 November
    { wasteId: 4, organisationId: 1, wasteType: "General", quantity: 20, disposalMethod: "Landfill", dateRecorded: "2026-11-10" },
    { wasteId: 5, organisationId: 1, wasteType: "Organic", quantity: 5, disposalMethod: "Composting", dateRecorded: "2026-11-12" },
    { wasteId: 6, organisationId: 2, wasteType: "General", quantity: 7, disposalMethod: "Landfill", dateRecorded: "2026-11-11" }
];


module.exports = {
    //1. Add a Record to WasteRecords[]
    addWasteRecord(organisationid, wastetype, quantity, disposalmethod, daterecorded) {
        let wasteid = wasteRecords.length + 1;

        wasteRecords.push({
            wasteId: wasteid,
            organisationId: organisationid,
            wasteType : wastetype,
            quantity : quantity,
            disposalMethod: disposalmethod,
            dateRecorded: daterecorded
        })
        return "Record added."
    },

    //2. Retrieves Waste Records by its Type
    filterWasteRecordByType(wastetype) {
        let result = [];
        for (let i = 0; i < wasteRecords.length; i++){
            if (wasteRecords[i].wasteType == wastetype) {
                result.push(wasteRecords[i]);
            }
        }
        return result;
    },

    //3. Retrieves Waste Records in a period
    getWasteByDateRange(startDate, endDate) {
        let result = [];
        for (let i =0; i < wasteRecords.length; i++) {
            if (startDate <= wasteRecords[i].dateRecorded && endDate >= wasteRecords[i].dateRecorded) {
                result.push(wasteRecords[i]);
            }
        }
        return result;
    },

    //4. calculates total waste by each organisation
    calculateWasteByOrganisation(organisationid) {
        let totalWaste = 0;
        let totalRecycled = 0;
        let totalLandfill = 0;
        let totalComposted = 0;
        let r = 0;

        for (let i = 0; i < wasteRecords.length; i++) {
            if (wasteRecords[i].organisationId == organisationid) {
                totalWaste += wasteRecords[i].quantity;
                if (wasteRecords[i].disposalMethod == "Recycling") {
                    totalRecycled += wasteRecords[i].quantity;
                } else if (wasteRecords[i].disposalMethod == "Landfill") {
                    totalLandfill += wasteRecords[i].quantity;
                } else if (wasteRecords[i].disposalMethod == "Composting") {
                    totalComposted += wasteRecords[i].quantity;
                }
            }
        }

        for (let i = 0; i < organisations.length; i ++) {
            if (organisations[i].organisationId == organisationid) {
                r = i;
            }
        }
        return {
            Organisation: organisations[r].name,
            "Total Waste": totalWaste,
            "Total Recycled":totalRecycled,
            "Total Landfill":totalLandfill,
            "Total Composted":totalComposted
        }
    },

    //5. Retrieves the waste type with the most recorded total waste
    getMostGeneratedWasteType() {
        let plasticTotal = 0;
        let paperTotal = 0;
        let generalTotal = 0;
        let organicTotal = 0;
        let q = 0;
        let n = "";

        for (let i = 0; i < wasteRecords.length; i++) {
            if (wasteRecords[i].wasteType == "Plastic") {
                plasticTotal += wasteRecords[i].quantity;
            } else if (wasteRecords[i].wasteType == "Paper") {
                paperTotal += wasteRecords[i].quantity;
            } else if (wasteRecords[i].wasteType == "General") {
                generalTotal += wasteRecords[i].quantity;
            } else if (wasteRecords[i].wasteType == "Organic") {
                organicTotal += wasteRecords[i].quantity;
            }
        }

        let type = {
            Plastic: plasticTotal,
            Paper: paperTotal,
            General: generalTotal,
            Organic: organicTotal
        };

        for (let i = 0; i < Object.values(type).length; i++) {
            if (Object.values(type)[i] > q) {
                q = Object.values(type)[i];
                n = Object.keys(type)[i];
            }
        }
        return {
            "Type": n,
            "Quantity": q
        };
    }
}